begin;
create temp table fx(id uuid, en text, w text, bn text, ja text, old_en text, old_w text) on commit drop;

create function pg_temp.k(n text, w text) returns text language sql immutable as
$$ select lower(regexp_replace(trim(coalesce(n,'')), '\s+', ' ', 'g')) || '|' || lower(regexp_replace(trim(coalesce(w,'')), '\s+', '', 'g')) $$;
do $$
declare n int; d int;
begin
  update deals dl set en = coalesce(fx.en, dl.en), w = coalesce(fx.w, dl.w)
    from fx where dl.archived_at is null and (fx.en is not null or fx.w is not null)
     and pg_temp.k(dl.en, dl.w) = pg_temp.k(fx.old_en, fx.old_w);
  get diagnostics d = row_count;
  update products p set en = coalesce(fx.en, p.en), w = coalesce(fx.w, p.w),
                        bn = coalesce(fx.bn, p.bn), ja = coalesce(fx.ja, p.ja)
    from fx where p.id = fx.id and p.archived_at is null and p.en = fx.old_en and coalesce(p.w,'') = fx.old_w;
  get diagnostics n = row_count;
  if n <> (select count(*) from fx) then raise exception 'expected % products, got % — nothing changed', (select count(*) from fx), n; end if;
  raise notice 'products fixed: %, deal cards kept in step: %', n, d;
end $$;
commit;
